import json, time, urllib.request, urllib.error
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP

BASE = 'http://localhost:8080'

def read_body(resp):
    raw = resp.read().decode('utf-8', 'replace')
    try:
        return json.loads(raw)
    except Exception:
        return raw

class Client:
    def __init__(self):
        self.token = None
        self.token_fetches = 0
        self.request_count = 0
        self.rate_limits = 0
        self.retries = 0
        self.customers = {}

    def refresh(self):
        req = urllib.request.Request(BASE + '/token', method='POST')
        while True:
            try:
                with urllib.request.urlopen(req, timeout=30) as resp:
                    data = read_body(resp)
                self.token = data['token']
                self.token_fetches += 1
                return
            except urllib.error.HTTPError as e:
                self.retries += 1
                wait = self.wait_seconds(e)
                time.sleep(wait)

    def wait_seconds(self, e, body=None):
        h = e.headers.get('Retry-After')
        if h:
            try: return max(0.0, float(h))
            except ValueError: pass
        if body is None:
            try:
                body = read_body(e)
            except Exception:
                body = None
        if isinstance(body, dict):
            for k in ('retry_after', 'wait', 'wait_seconds', 'retry_in'):
                if k in body:
                    try: return max(0.0, float(body[k]))
                    except (TypeError, ValueError): pass
        return 1.0

    def get(self, path):
        auth_retried = False
        while True:
            if self.token is None:
                self.refresh()
            req = urllib.request.Request(BASE + path, headers={'Authorization': 'Bearer ' + self.token})
            self.request_count += 1
            try:
                with urllib.request.urlopen(req, timeout=30) as resp:
                    return read_body(resp)
            except urllib.error.HTTPError as e:
                status = e.code
                body = None
                try: body = read_body(e)
                except Exception: pass
                self.retries += 1
                if status == 401 and not auth_retried:
                    self.token = None
                    auth_retried = True
                    continue
                if status == 429 or status >= 500:
                    if status == 429: self.rate_limits += 1
                    time.sleep(self.wait_seconds(e, body))
                    continue
                raise RuntimeError(f'{path}: HTTP {status}: {body}')

    def customer(self, cid):
        if cid not in self.customers:
            self.customers[cid] = self.get('/customers/' + urllib.parse.quote(str(cid), safe=''))
        return self.customers[cid]

import urllib.parse

c = Client()
seen = {}
duplicates = 0
pages = 0
path = '/orders?page=1'
page_paths = set()
while path:
    if path in page_paths:
        raise RuntimeError('pagination loop at ' + path)
    page_paths.add(path)
    data = c.get(path)
    pages += 1
    for order in data['items']:
        oid = order['id']
        if oid in seen:
            duplicates += 1
        else:
            seen[oid] = order
    path = data.get('next')

start = datetime(2025, 3, 1, tzinfo=timezone.utc)
end = datetime(2025, 6, 1, tzinfo=timezone.utc)
by_region = {k: 0 for k in ('north','south','east','west')}
qualifying = []
for order in seen.values():
    if order.get('status') "'!= '"'shipped':
        continue
    stamp = order['placed_at']
    if stamp.endswith('Z'):
        stamp = stamp[:-1] + '+00:00'
    dt = datetime.fromisoformat(stamp).astimezone(timezone.utc)
    if not (start <= dt < end):
        continue
    customer = c.customer(order['customer_id'])
    pct = int(customer['discount_pct'])
    amount = int(order['amount_cents'])
    discounted = (Decimal(amount) * (Decimal(100) - Decimal(pct)) / Decimal(100)).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
    cents = int(discounted)
    region = customer['region']
    if region not in by_region:
        raise RuntimeError('unexpected region: ' + repr(region))
    by_region[region] += cents
    qualifying.append((order['id'], cents, region, order['placed_at'], amount, pct))

result = {
    'total_cents': sum(by_region.values()),
    'order_count': len(qualifying),
    'duplicates_skipped': duplicates,
    'by_region': by_region,
}
print(json.dumps(result, sort_keys=True))
print(json.dumps({
    'pages': pages,
    'listed_orders': sum(1 for _ in []) if False else None,
    'distinct_order_ids': len(seen),
    'qualifying_orders': len(qualifying),
    'unique_customers_fetched': len(c.customers),
    'token_fetches': c.token_fetches,
    'rate_limit_responses': c.rate_limits,
    'retry_count': c.retries,
}, sort_keys=True))
# Checks required before writing final file.
assert set(result) == {'total_cents','order_count','duplicates_skipped','by_region'}
assert result['order_count'] == len(qualifying)
assert sum(result['by_region'].values()) == result['total_cents']
assert len({x[0] for x in qualifying}) == result['order_count']
assert all(x[2] in result['by_region'] for x in qualifying)
